    dividers = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            dividers.append(("h", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            dividers.append(("v", c, vals[0]))

    panels = []
    for orient, ix, _ in dividers:
        if orient == "h":
            a, b = grid[:ix], grid[ix + 1:]
            if a and b and len(a) == len(b):
                panels.append((orient, a, b))
        else:
            a = [row[:ix] for row in grid]
            b = [row[ix + 1:] for row in grid]
            if a and b and len(a[0]) == len(b[0]):
                panels.append((orient, a, b))
    if not panels:
        raise ValueError("No valid uniform panel divider found")

    # Choose the panel with the sparsest non-background color as the marker panel.
    best = None
    for orient, a, b in panels:
        for marker_panel, reference_panel, swapped in ((a, b, False), (b, a, True)):
            bg = Counter(x for row in marker_panel for x in row).most_common(1)[0][0]
            marker_counts = Counter(x for row in marker_panel for x in row)
            marker = max((c for c in marker_counts if c != bg), key=marker_counts.get)
            marker_n = marker_counts[marker]
            score = marker_n / (len(marker_panel) * len(marker_panel[0]))
            candidate = (score, orient, a, b, marker_panel, reference_panel, marker, swapped)
