                best = candidate

    _, orient, a, b, marker_panel, reference_panel, marker, _ = best
    ref_bg = Counter(x for row in reference_panel for x in row).most_common(1)[0][0]
    out = [[marker for _ in row] for row in marker_panel]
    for r in range(len(marker_panel)):
        for c in range(len(marker_panel[0])):
            if marker_panel[r][c] == marker and reference_panel[r][c] != ref_bg:
                out[r][c] = 3
    return out


